function Invoke-ProSoakRetire($Session,$Guard,[string]$ProNonce,[string]$ScriptDirectory){
 $meta=$Guard.ReadCommand('soak-inputs.json')|ConvertFrom-Json;if($meta.caseId -notmatch '^[a-f0-9]{32}$' -or $meta.proNonce -ne $ProNonce){throw 'Bound soak case required'}
 $source=Join-Path $ScriptDirectory 'pro-soak-retire.mjs';$Guard.PinInputFile($source);$hash=(Get-FileHash -LiteralPath $source).Hash.ToLowerInvariant()
 $destination=Invoke-Command -Session $Session -ArgumentList $meta.caseId -ScriptBlock {
  param($caseId)
  $ErrorActionPreference='Stop';$prefix='C:\MuLab\public\soak-'+$caseId;$approved='C:\MuLab\approved\soak-'+$caseId;$cfg=[IO.File]::ReadAllText($approved+'-config.json')|ConvertFrom-Json;$prior=[IO.File]::ReadAllText($approved+'-result.json')|ConvertFrom-Json;$all=@(Get-VM)
  $preserved=[IO.File]::ReadAllText($approved+'-preserved.json')|ConvertFrom-Json;if(-not $preserved.complete -or -not $preserved.sourceUnchanged -or $preserved.caseId -ne $caseId -or $preserved.originalId -ne $prior.nested.id -or $preserved.platformId -ne $prior.nested.platformId){throw 'Verified original archive required before retirement'}
  if($cfg.caseId -ne $caseId -or $cfg.tools -ne ('C:\MuLab\soak-tools\'+$caseId) -or $prior.complete -ne $false -or -not $prior.processExitConfirmed -or -not $prior.brokerExitConfirmed -or -not $prior.nested.confirmedOff -or $prior.nested.removed -or $all.Count -ne 1 -or [string]$all[0].Id -ne $prior.nested.platformId -or [string]$all[0].State -ne 'Off'){throw 'Only the exact terminal stopped failed soak fixture may retire'}
  $busy=@(Get-CimInstance Win32_Process|Where-Object{($_.ExecutablePath -eq $cfg.node -and $_.CommandLine -like ('*'+$caseId+'*')) -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-*.exe'});if($busy.Count -or (Test-Path ($prefix+'-retire-owner.json')) -or (Get-ScheduledTask -TaskName ('MuPro-soak-retire-'+$caseId) -ErrorAction SilentlyContinue)){throw 'Existing actors or retirement work must be inspected'}
  $file=Join-Path $cfg.tools 'pro-soak-retire.mjs';if(Test-Path $file){throw 'Existing retirement source preserved'};return $file
 }
 if($destination -ne ('C:\MuLab\soak-tools\'+$meta.caseId+'\pro-soak-retire.mjs')){throw 'Retirement destination changed'};Copy-Item -LiteralPath $source -Destination $destination -ToSession $Session
 return Invoke-Command -Session $Session -ArgumentList $meta.caseId,$hash -ScriptBlock {
  param($caseId,$hash)
  $ErrorActionPreference='Stop';$prefix='C:\MuLab\public\soak-'+$caseId;$approved='C:\MuLab\approved\soak-'+$caseId;$cfg=[IO.File]::ReadAllText($approved+'-config.json')|ConvertFrom-Json;$script=Join-Path $cfg.tools 'pro-soak-retire.mjs';if((Get-FileHash $script).Hash.ToLowerInvariant() -ne $hash -or (Get-FileHash $cfg.node).Hash.ToLowerInvariant() -ne $cfg.nodeSha256){throw 'Retirement source/runtime changed'}
  $task='MuPro-soak-retire-'+$caseId;$ownerFile=$prefix+'-retire-owner.json';$resultFile=$prefix+'-retire-result.json';$launch='$env:PSModulePath=Join-Path $PSHOME ''Modules''; & '''+$cfg.node+''' --no-warnings '''+$script+''' '+$caseId+' *> '''+$prefix+'-retire-client.log'';exit $LASTEXITCODE';$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($launch));$principal=New-ScheduledTaskPrincipal -UserId 'MU-PRO-LAB\MuLabUser' -LogonType Interactive -RunLevel Limited;$action=New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe') -Argument ('-NoProfile -NonInteractive -WindowStyle Hidden -EncodedCommand '+$encoded) -WorkingDirectory C:\MuLab\public;$settings=New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::FromMinutes(10)) -MultipleInstances IgnoreNew;Register-ScheduledTask -TaskName $task -Action $action -Principal $principal -Settings $settings|Out-Null;Start-ScheduledTask -TaskName $task
  $until=[DateTime]::UtcNow.AddMinutes(3);while(-not(Test-Path $ownerFile)){if([DateTime]::UtcNow -gt $until){throw 'Retirement owner missing; preserve task'};Start-Sleep -Milliseconds 200};$owner=[IO.File]::ReadAllText($ownerFile)|ConvertFrom-Json;$actor=Get-CimInstance Win32_Process -Filter ('ProcessId='+[int]$owner.pid);if($owner.caseId -ne $caseId -or $owner.nonce -notmatch '^[a-f0-9]{64}$' -or $actor.ExecutablePath -ne $cfg.node -or $actor.CommandLine -notlike ('*'+$script+'*'+$caseId+'*') -or (Invoke-CimMethod -InputObject $actor -MethodName GetOwnerSid).Sid -ne $cfg.userSid){throw 'Retirement controller binding changed'};$handle=Get-Process -Id $owner.pid;$null=$handle.Handle
  $bin=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/bin';$artifact=[IO.File]::ReadAllText((Join-Path $bin 'current.json'))|ConvertFrom-Json;$broker=Join-Path $bin $artifact.brokerFile;if($artifact.sourceDigest -ne $cfg.sourceDigest -or (Get-FileHash $broker).Hash.ToLowerInvariant() -ne $artifact.brokerSha256){throw 'Retirement protected broker changed'};$agent=Start-Process -FilePath $broker -ArgumentList @('--owner',[string]$owner.pid,'--pipe',[string]$owner.nonce,'--detect-host') -WorkingDirectory $bin -WindowStyle Hidden -RedirectStandardOutput ($approved+'-retire-broker-out.log') -RedirectStandardError ($approved+'-retire-broker-error.log') -PassThru;$null=$agent.Handle;$until=[DateTime]::UtcNow.AddMinutes(6)
  do{if(Test-Path $resultFile){if(-not $handle.WaitForExit(15000) -or -not $agent.WaitForExit(45000)){throw 'Retirement actors remain live'};$result=[IO.File]::ReadAllText($resultFile)|ConvertFrom-Json;if($result.caseId -ne $caseId -or $result.pid -ne $owner.pid -or $result.nonce -cne $owner.nonce){throw 'Retirement result binding changed'};$result|Add-Member -NotePropertyName processExitConfirmed -NotePropertyValue $true;$result|Add-Member -NotePropertyName brokerExitConfirmed -NotePropertyValue $true;[IO.File]::WriteAllText($approved+'-retire-result.json',($result|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));Unregister-ScheduledTask -TaskName $task -Confirm:$false;return $result};if($handle.HasExited){throw 'Retirement exited without receipt'};if([DateTime]::UtcNow -gt $until){throw 'Retirement remains unconfirmed; inspect live processes'};Start-Sleep -Milliseconds 200}while($true)
 }
}
